import {FaceTracker,project} from './tracking.js';
import {allowedHolds} from './core.js';
let ready;
export function loadVision(){if(ready)return ready;ready=new Promise((resolve,reject)=>{const script=document.createElement('script');let timer=setTimeout(()=>reject(Error('O módulo de visão demorou para iniciar. Recarregue e tente novamente.')),30000);const done=()=>{clearTimeout(timer);resolve({cv:window.cv});};script.src='./vendor/opencv.js';script.onload=()=>{if(window.cv?.Mat)done();else if(window.cv)window.cv.onRuntimeInitialized=done;else reject(Error('Módulo de visão indisponível.'));};script.onerror=()=>{clearTimeout(timer);reject(Error('Não foi possível carregar o módulo de visão. Confira os arquivos da publicação.'));};document.head.append(script);}).catch(e=>{ready=null;throw e});return ready;}
export function cameraError(error){return ({NotAllowedError:'Acesso à câmera negado. Permita a câmera nas configurações deste site e tente novamente.',NotFoundError:'Nenhuma câmera foi encontrada neste aparelho.',NotReadableError:'A câmera está ocupada por outro aplicativo.',OverconstrainedError:'Esta câmera não atende à configuração solicitada.'})[error.name]||error.message||'Não foi possível iniciar a câmera.';}
export class CameraSession{
 constructor({video,overlay,status}){Object.assign(this,{video,overlay,status});this.token=0;this.active=false;this.frame=document.createElement('canvas');this.layer=document.createElement('canvas');this.dim=.72;}
 say(text){this.status.textContent=text;}
 async start(route){this.stop();const token=++this.token;this.active=true;this.route=route;this.say('Iniciando câmera…');try{if(!window.isSecureContext)throw Error('A câmera exige HTTPS ou localhost. Abra o endereço seguro do Netlify.');if(!navigator.mediaDevices?.getUserMedia)throw Error('Este navegador não disponibiliza câmera. Abra o site no Chrome ou Safari do aparelho.');let timer;const request=navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false}).then(stream=>{if(token!==this.token)stream.getTracks().forEach(t=>t.stop());return stream;});let stream;try{stream=await Promise.race([request,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('A câmera não respondeu. Confira a permissão do navegador ou abra no navegador do aparelho.')),15000);})]);}finally{clearTimeout(timer);}if(token!==this.token)return;this.stream=stream;this.video.srcObject=stream;await this.video.play();this.say('Carregando reconhecimento das faces…');const {cv}=await loadVision();if(token!==this.token)return;this.cv=cv;this.tracker=new FaceTracker(cv);this.key=JSON.stringify(route.snapshot.faces.map(f=>[f.id,f.photo]));for(const face of route.snapshot.faces){const image=new Image();image.src=face.photo;await image.decode();if(token!==this.token)return;const canvas=document.createElement('canvas'),scale=Math.min(1,800/image.width);canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const gray=this.gray(canvas);try{this.tracker.add(face.id,gray)}finally{gray.delete()}}this.say('Enquadre uma face inteira, com boa luz.');this.tick(token);}catch(error){if(token===this.token){this.stop();this.say(cameraError(error));}}}
 gray(source){const rgba=this.cv.imread(source),gray=new this.cv.Mat();this.cv.cvtColor(rgba,gray,this.cv.COLOR_RGBA2GRAY);rgba.delete();return gray;}
 tick(token){if(token!==this.token||!this.active)return;if(document.hidden){this.stop();this.say('Câmera desligada ao sair da página. Inicie novamente.');return;}try{if(this.video.readyState>=2){const scale=Math.min(1,800/this.video.videoWidth),w=Math.round(this.video.videoWidth*scale),h=Math.round(this.video.videoHeight*scale);if(!w||!h)throw Error('Câmera sem imagem.');this.frame.width=w;this.frame.height=h;this.frame.getContext('2d',{willReadFrequently:true}).drawImage(this.video,0,0,w,h);const gray=this.gray(this.frame);let found;try{found=this.tracker.locate(gray)}finally{gray.delete()}this.draw(found,w,h);this.say(found.length?`${found.length} de ${this.route.snapshot.faces.length} faces reconhecidas · confira o alinhamento`:'Sem alinhamento confiável. Destaques ocultos; reenquadre a face.');}}catch(error){this.stop();this.say('Rastreamento interrompido: '+cameraError(error));return;}this.timer=setTimeout(()=>this.tick(token),160);}
 draw(found,w,h){this.overlay.width=w;this.overlay.height=h;this.layer.width=w;this.layer.height=h;const ctx=this.overlay.getContext('2d'),shade=this.layer.getContext('2d');const path=(g,points)=>{g.beginPath();points.forEach((p,i)=>i?g.lineTo(...p):g.moveTo(...p));g.closePath()};shade.fillStyle=`rgba(0,0,0,${this.dim})`;for(const f of found){path(shade,f.quad);shade.fill();}const allowed=allowedHolds(this.route),polygons=[];for(const f of found)for(const hold of this.route.snapshot.holds.filter(h=>h.faceId===f.id&&allowed.has(h.id))){const points=hold.contour?.length?hold.contour.map(([x,y])=>project(f.H,x*f.width,y*f.height)):Array.from({length:24},(_,i)=>{const angle=i/24*Math.PI*2;return project(f.H,hold.x*f.width+Math.cos(angle)*hold.radius*f.width,hold.y*f.height+Math.sin(angle)*hold.radius*f.width)});if(points.some(p=>!p))continue;polygons.push({points,hold});}shade.globalCompositeOperation='destination-out';shade.fillStyle='#000';for(const p of polygons){path(shade,p.points);shade.fill();}ctx.drawImage(this.layer,0,0);for(const {points,hold}of polygons){const roles=this.route.assignments[hold.id]??[],start=roles.some(r=>r.startsWith('start')),end=roles.some(r=>r.startsWith('finish'));ctx.strokeStyle=start?'#99dba4':end?'#f39887':'#f5c177';ctx.lineWidth=2;path(ctx,points);ctx.stroke();ctx.font='bold 14px sans-serif';ctx.fillStyle='white';ctx.strokeStyle='#191714';ctx.lineWidth=3;const label=start?'S':end?'F':roles.includes('foot')||!roles.length?'P':'M';ctx.strokeText(label,...points[Math.min(18,points.length-1)]);ctx.fillText(label,...points[Math.min(18,points.length-1)]);}}
 changeRoute(route){if(!this.active)return;const key=JSON.stringify(route.snapshot.faces.map(f=>[f.id,f.photo]));if(key!==this.key){this.stop();this.say('A montagem mudou. Inicie a câmera para reconhecer as novas fotos.');return;}this.route=route;this.overlay.getContext('2d').clearRect(0,0,this.overlay.width,this.overlay.height);}
 stop(){this.token++;this.active=false;clearTimeout(this.timer);this.stream?.getTracks().forEach(t=>t.stop());this.stream=null;this.video.srcObject=null;this.tracker?.dispose();this.tracker=null;this.overlay.getContext('2d').clearRect(0,0,this.overlay.width,this.overlay.height);}
}

